import { expect, test, uniqueName } from "../../fixtures";

test.describe("AUD-02 vendor audit trail tenant isolation", () => {
  test(
    "audit trails from another tenant are invisible",
    { tag: "@AUD-02" },
    async ({ apiAs }) => {
      // Arrange: a vendor exists in the Globex Procurement tenant.
      const globex = await apiAs("otherTenant");
      const createResponse = await globex.post("/api/vendors", {
        data: {
          name: uniqueName("Globex Audit Vendor"),
          category: "services",
          contact_email: `audit-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@globex.test`,
        },
      });
      expect(createResponse.status(), "create vendor in Globex tenant").toBe(201);
      const vendorId = ((await createResponse.json()) as { id: string }).id;

      // Act: a Northwind member requests that vendor's audit trail.
      const member = await apiAs("member");
      const response = await member.get(`/api/vendors/${vendorId}/audit`);

      // Assert
      expect(response.status()).toBe(404);
    },
  );
});
